{
  "name": "Customized Bicycle Manufacturing Process",
  "resources": [
    {
      "name": "Sales Department",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "Storehouse",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "Engineering Department",
      "capacity": 1,
      "resource_type": "department"
    }
  ],
  "events": [
    {
      "id": "event_start_order",
      "name": "Order received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Order"
    },
    {
      "id": "event_end_rejected",
      "name": "Order rejected",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_msg_to_storehouse",
      "name": "Inform storehouse",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Order Part List Information"
    },
    {
      "id": "event_msg_to_engineering",
      "name": "Inform engineering",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Order Preparation Request"
    },
    {
      "id": "event_sh_start",
      "name": "Order notification received by Storehouse",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Order Part List Information"
    },
    {
      "id": "event_sh_end",
      "name": "Parts reservation completed",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Parts Ready Notification"
    },
    {
      "id": "event_eng_start",
      "name": "Order notification received by Engineering",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Order Preparation Request"
    },
    {
      "id": "event_parts_ready_received",
      "name": "Parts ready notification received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Parts Ready Notification"
    },
    {
      "id": "event_end_shipped",
      "name": "Bicycle shipped and order completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_evaluate_order",
      "name": "Evaluate order (accept or reject)",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Sales Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_process_part_list",
      "name": "Process part list and check required quantity",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Storehouse",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": true,
      "input_data_ids": [
        "data_part_list"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_reserve_part",
      "name": "Reserve part",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Storehouse",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_part_list"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_backorder_part",
      "name": "Back-order part",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Storehouse",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_part_list"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_prepare_assembly",
      "name": "Prepare everything for assembly",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Engineering Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_assemble_bicycle",
      "name": "Assemble bicycle",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Engineering Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_part_list"
      ],
      "output_data_ids": [
        "data_bicycle"
      ]
    },
    {
      "id": "task_ship_bicycle",
      "name": "Ship bicycle to customer",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Sales Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_bicycle"
      ],
      "output_data_ids": []
    }
  ],
  "gateways": [
    {
      "id": "gw_accept_or_reject",
      "name": "Order accepted?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_reject",
          "condition": "Rejected"
        },
        {
          "flow_id": "flow_accept",
          "condition": "Accepted"
        }
      ]
    },
    {
      "id": "gw_sales_parallel_split",
      "name": "Inform departments",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_part_availability",
      "name": "Part available in-house?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_part_avail",
          "condition": "Available"
        },
        {
          "flow_id": "flow_part_not_avail",
          "condition": "Not available"
        }
      ]
    },
    {
      "id": "gw_part_processed_join",
      "name": "Part processing joined",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_more_parts",
      "name": "More parts on list?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_loop_parts",
          "condition": "Yes"
        },
        {
          "flow_id": "flow_all_parts_done",
          "condition": "No (All items processed)"
        }
      ]
    },
    {
      "id": "gw_eng_join",
      "name": "Preparation and parts ready?",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "flow_s1",
      "source_id": "event_start_order",
      "target_id": "task_evaluate_order",
      "condition_name": null
    },
    {
      "id": "flow_s2",
      "source_id": "task_evaluate_order",
      "target_id": "gw_accept_or_reject",
      "condition_name": null
    },
    {
      "id": "flow_reject",
      "source_id": "gw_accept_or_reject",
      "target_id": "event_end_rejected",
      "condition_name": "Rejected"
    },
    {
      "id": "flow_accept",
      "source_id": "gw_accept_or_reject",
      "target_id": "gw_sales_parallel_split",
      "condition_name": "Accepted"
    },
    {
      "id": "flow_s3",
      "source_id": "gw_sales_parallel_split",
      "target_id": "event_msg_to_storehouse",
      "condition_name": null
    },
    {
      "id": "flow_s4",
      "source_id": "gw_sales_parallel_split",
      "target_id": "event_msg_to_engineering",
      "condition_name": null
    },
    {
      "id": "flow_s5",
      "source_id": "event_msg_to_storehouse",
      "target_id": "task_ship_bicycle",
      "condition_name": null
    },
    {
      "id": "flow_s6",
      "source_id": "event_msg_to_engineering",
      "target_id": "task_ship_bicycle",
      "condition_name": null
    },
    {
      "id": "flow_s7",
      "source_id": "task_ship_bicycle",
      "target_id": "event_end_shipped",
      "condition_name": null
    },
    {
      "id": "flow_sh1",
      "source_id": "event_sh_start",
      "target_id": "task_process_part_list",
      "condition_name": null
    },
    {
      "id": "flow_sh2",
      "source_id": "task_process_part_list",
      "target_id": "gw_part_availability",
      "condition_name": null
    },
    {
      "id": "flow_part_avail",
      "source_id": "gw_part_availability",
      "target_id": "task_reserve_part",
      "condition_name": "Available"
    },
    {
      "id": "flow_part_not_avail",
      "source_id": "gw_part_availability",
      "target_id": "task_backorder_part",
      "condition_name": "Not available"
    },
    {
      "id": "flow_sh3",
      "source_id": "task_reserve_part",
      "target_id": "gw_part_processed_join",
      "condition_name": null
    },
    {
      "id": "flow_sh4",
      "source_id": "task_backorder_part",
      "target_id": "gw_part_processed_join",
      "condition_name": null
    },
    {
      "id": "flow_sh5",
      "source_id": "gw_part_processed_join",
      "target_id": "gw_more_parts",
      "condition_name": null
    },
    {
      "id": "flow_loop_parts",
      "source_id": "gw_more_parts",
      "target_id": "task_process_part_list",
      "condition_name": "Yes"
    },
    {
      "id": "flow_all_parts_done",
      "source_id": "gw_more_parts",
      "target_id": "event_sh_end",
      "condition_name": "No (All items processed)"
    },
    {
      "id": "flow_eng1",
      "source_id": "event_eng_start",
      "target_id": "task_prepare_assembly",
      "condition_name": null
    },
    {
      "id": "flow_eng2",
      "source_id": "task_prepare_assembly",
      "target_id": "gw_eng_join",
      "condition_name": null
    },
    {
      "id": "flow_eng3",
      "source_id": "event_parts_ready_received",
      "target_id": "gw_eng_join",
      "condition_name": null
    },
    {
      "id": "flow_eng4",
      "source_id": "gw_eng_join",
      "target_id": "task_assemble_bicycle",
      "condition_name": null
    }
  ],
  "pools": [
    {
      "id": "pool_sales",
      "name": "Sales Department",
      "element_ids": [
        "event_start_order",
        "task_evaluate_order",
        "gw_accept_or_reject",
        "event_end_rejected",
        "gw_sales_parallel_split",
        "event_msg_to_storehouse",
        "event_msg_to_engineering",
        "task_ship_bicycle",
        "event_end_shipped"
      ]
    },
    {
      "id": "pool_storehouse",
      "name": "Storehouse",
      "element_ids": [
        "event_sh_start",
        "task_process_part_list",
        "gw_part_availability",
        "task_reserve_part",
        "task_backorder_part",
        "gw_part_processed_join",
        "gw_more_parts",
        "event_sh_end"
      ]
    },
    {
      "id": "pool_engineering",
      "name": "Engineering Department",
      "element_ids": [
        "event_eng_start",
        "task_prepare_assembly",
        "event_parts_ready_received",
        "gw_eng_join",
        "task_assemble_bicycle"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_sales_to_storehouse",
      "source_id": "event_msg_to_storehouse",
      "target_id": "event_sh_start",
      "name": "Inform Storehouse of Order"
    },
    {
      "id": "mf_sales_to_engineering",
      "source_id": "event_msg_to_engineering",
      "target_id": "event_eng_start",
      "name": "Inform Engineering of Order"
    },
    {
      "id": "mf_storehouse_to_engineering",
      "source_id": "event_sh_end",
      "target_id": "event_parts_ready_received",
      "name": "Parts Reserved/Back-ordered Notification"
    }
  ],
  "data_objects": [
    {
      "id": "data_order",
      "name": "Order"
    },
    {
      "id": "data_part_list",
      "name": "Part List"
    },
    {
      "id": "data_bicycle",
      "name": "Customized Bicycle"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
